package net.officefloor.hq.app.plan;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimRules;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/**
 * For every plan on the sheet, in the order they were added, makes a DRAFT claim with the plan's amount for each plan
 * date (the start, then every N days) up to its end and the sheet's today that has none yet, dated that day with an
 * empty note, by the claim form's rules: a date the form refuses is skipped, and tried again next time. Each claim is
 * recorded and logged as the claim form records and logs it.
 */
public class GeneratePlans {
    public void generate(@Val Sheet sheet, PlanRepository plans, PlanClaimRepository made, PersonRepository people,
            ClaimRepository claims, PeriodRepository periods, PersonGradeRepository grades, RateRepository rates,
            ClaimLogRepository log, HolidayRepository holidays,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit,
            Out<GeneratedPlans> madeOut) {
        String by = AuditUser.decode(user);
        int count = 0;
        for (Plan plan : plans.findBySheetIdOrderByIdAsc(sheet.getId())) {
            Person person = people.findByIdAndSheetId(plan.getPersonId(), sheet.getId()).orElse(null);
            if (person == null) {
                continue;
            }
            Set<LocalDate> done = new HashSet<>();
            made.findByPlanId(plan.getId()).forEach(m -> done.add(m.getOnDate()));
            for (LocalDate date : plan.datesUpTo(sheet.getToday())) {
                if (done.contains(date)) {
                    continue;
                }
                Claim claim;
                try {
                    claim = ClaimRules.make(new ClaimInput(plan.getAmount(), date, "", null, null, null), sheet,
                            person, claims, periods, grades, holidays);
                } catch (InvalidClaimException e) {
                    continue;
                }
                claim = claims.saveAndFlush(claim);
                made.saveAndFlush(new PlanClaim(plan.getId(), date, claim.getId()));
                ClaimRules.auditAdded(claim, person.getName(), by, audit);
                ClaimRules.log(claim, sheet, log, people, rates, grades, by);
                count++;
            }
        }
        madeOut.set(new GeneratedPlans(count));
    }
}
package net.officefloor.hq.app.plan;

/** A plan as the screen shows it: its person, amount (two decimals), start, every N days or day of the month (the other
 *  null), end and how many claims it has made so far. */
public record PlanResponse(Long id, Long personId, String amount, String start, Integer every, Integer day, String end,
        long generated) {

    public static PlanResponse of(Plan plan, PlanClaimRepository made) {
        return new PlanResponse(plan.getId(), plan.getPersonId(), plan.getAmount().setScale(2).toPlainString(),
                plan.getStart().toString(), plan.getEvery(), plan.getDay(),
                plan.getEnd().toString(), made.countByPlanId(plan.getId()));
    }
}
package net.officefloor.hq.app.plan;

import java.util.List;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** The sheet's plans, in the order they were added. */
public class RespondWithPlans {
    public void respond(@Val Sheet sheet, PlanRepository plans, PlanClaimRepository made,
            ObjectResponse<List<PlanResponse>> response) {
        response.send(plans.findBySheetIdOrderByIdAsc(sheet.getId()).stream()
                .map(p -> PlanResponse.of(p, made)).toList());
    }
}
package net.officefloor.hq.app.plan;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** A person's plan: an amount, a start date, either every N days (at least 1) or monthly on a day of the month (1 to
 *  31), and an end date (not before the start). */
@Entity
@Table(name = "plan")
public class Plan {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(nullable = false)
    private BigDecimal amount;

    @Column(name = "start_date", nullable = false)
    private LocalDate start;

    @Column(name = "every_days")
    private Integer every;

    @Column(name = "month_day")
    private Integer day;

    @Column(name = "end_date", nullable = false)
    private LocalDate end;

    protected Plan() {
    }

    public Plan(String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every, Integer day,
            LocalDate end) {
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.start = start;
        this.every = every;
        this.day = day;
        this.end = end;
    }

    /** The plan's dates, up to its end and the given day: the start then every N days, or for a monthly plan its day
     *  in every month from the start's month (a day beyond the month's length on its last day), those before the start
     *  left out. */
    public List<LocalDate> datesUpTo(LocalDate today) {
        LocalDate last = today != null && today.isBefore(end) ? today : end;
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
                LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
                if (!d.isBefore(start) && !d.isAfter(last)) {
                    dates.add(d);
                }
            }
            return dates;
        }
        for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
            dates.add(d);
        }
        return dates;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getStart() {
        return start;
    }

    public Integer getEvery() {
        return every;
    }

    public Integer getDay() {
        return day;
    }

    public LocalDate getEnd() {
        return end;
    }
}
