export type Plan = {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number | null;
  day: number | null;
  end: string;
  generated: number;
};

export const plansQueryKey = (sheetId: string) => ['sheet', sheetId, 'plans'] as const;

export const plansPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/plans`;

/** The sheet's plans, in the order they were added. */
